import './compat.mjs';
const $=id=>document.getElementById(id), canvas=$('canvas'), ctx=canvas.getContext('2d');
const ids=['font','paper','size','ink','background','tone','fontSize','variation','spacing'];let pages=[],current=0,seed=1729,timer,customFontData=null,busy=false;
$('text').value='Aplicación de los n-gramas en un RAG hospitalario\n\nUn modelo de n-gramas estima qué palabra puede aparecer después de las anteriores. Aprende a partir de la frecuencia de las secuencias en un conjunto de textos.\n\nPor ejemplo, después de «criterios de», puede sugerir «inclusión» o «exclusión». Estas sugerencias reflejan patrones del lenguaje; no constituyen una recomendación médica.\n\nElige una letra y un tipo de papel. Después, importa tu documento o pega aquí el texto completo.';
function settings(){return Object.fromEntries(ids.map(id=>[id,$(id).value]));}function status(s){$('status').textContent=s;}function rng(s){return()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296;};}
function metrics(s){return{w:1240,h:s.size==='letter'?1605:1754,margin:112,size:+s.fontSize,spacing:+s.spacing};}
function paginate(text,s){const m=metrics(s),max=m.w-m.margin*2-20;ctx.font=`${m.size}px ${s.font}`;const lines=[];for(const para of text.replace(/\r\n?/g,'\n').split('\n')){if(!para.trim()){lines.push('');continue;}let line='';for(const word of para.split(/\s+/).filter(Boolean)){if(ctx.measureText(line?line+' '+word:word).width<=max){line=line?line+' '+word:word;}else{if(line)lines.push(line);line='';for(const char of word){if(ctx.measureText(line+char).width>max&&line){lines.push(line);line='';}line+=char;}}}if(line)lines.push(line);}const n=Math.max(1,Math.floor((m.h-2*m.margin-40)/m.spacing));const out=[];for(let i=0;i<lines.length;i+=n)out.push(lines.slice(i,i+n));return out.length?out:[[]];}
function draw(target,page,s,index){const c=target.getContext('2d'),m=metrics(s),desk=s.background==='desk',pad=desk?84:0;target.width=m.w+pad*2;target.height=m.h+pad*2;const r=rng(seed+index*1001);if(desk){c.fillStyle='#a98b68';c.fillRect(0,0,target.width,target.height);for(let y=0;y<target.height;y+=6){c.strokeStyle=`rgba(68,42,20,${r()*.055})`;c.beginPath();c.moveTo(0,y);c.bezierCurveTo(400,y+r()*10,900,y-r()*10,target.width,y);c.stroke();}c.shadowColor='#35251255';c.shadowBlur=30;c.shadowOffsetY=12;}c.fillStyle=s.tone;c.fillRect(pad,pad,m.w,m.h);c.shadowBlur=0;c.shadowOffsetY=0;c.save();c.translate(pad,pad);c.strokeStyle='#8baac133';c.lineWidth=1.1;const y0=m.margin+7;if(s.paper==='ruled'){for(let y=y0;y<m.h-m.margin+10;y+=m.spacing){c.beginPath();c.moveTo(60,y);c.lineTo(m.w-60,y);c.stroke();}c.strokeStyle='#d0979255';c.beginPath();c.moveTo(88,55);c.lineTo(88,m.h-55);c.stroke();}else if(s.paper==='grid'){for(let x=60;x<m.w-60;x+=32){c.beginPath();c.moveTo(x,55);c.lineTo(x,m.h-55);c.stroke();}for(let y=55;y<m.h-55;y+=32){c.beginPath();c.moveTo(60,y);c.lineTo(m.w-60,y);c.stroke();}}else if(s.paper==='dots'){c.fillStyle='#849c9c55';for(let x=64;x<m.w-64;x+=32)for(let y=55;y<m.h-55;y+=32){c.beginPath();c.arc(x,y,1.3,0,Math.PI*2);c.fill();}}
c.fillStyle=s.ink;c.font=`${m.size}px ${s.font}`;c.textBaseline='alphabetic';const v=+s.variation/100;page.forEach((line,i)=>{let x=m.margin+(r()-.5)*v*7;const base=m.margin+i*m.spacing;for(const char of line){const w=c.measureText(char).width;c.save();c.translate(x,base+(r()-.5)*v*5);c.rotate((r()-.5)*v*.055);c.globalAlpha=.96+r()*.04;c.fillText(char,0,0);c.restore();x+=w;}});c.font='20px system-ui';c.fillStyle='#7c8176';c.textAlign='center';c.fillText(String(index+1),m.w/2,m.h-48);c.restore();}
async function render(){const s=settings();await document.fonts.load(`${s.fontSize}px ${s.font}`);pages=paginate($('text').value,s);current=Math.min(current,pages.length-1);show();$('count').textContent=`${$('text').value.length.toLocaleString('es')} caracteres`;$('fontSizeValue').textContent=s.fontSize;$('variationValue').textContent=s.variation+'%';$('spacingValue').textContent=s.spacing;}
function show(){draw(canvas,pages[current]||[],settings(),current);$('pageInfo').textContent=`Hoja ${current+1} de ${pages.length}`;$('navInfo').textContent=`${current+1} / ${pages.length}`;$('prev').disabled=current===0;$('next').disabled=current>=pages.length-1;}
ids.forEach(id=>$(id).addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(render,130);}));$('text').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(render,250);});$('prev').onclick=()=>{current--;show();};$('next').onclick=()=>{current++;show();};$('clear').onclick=()=>{$('text').value='';current=0;render();};$('reseed').onclick=()=>{seed=Math.floor(Math.random()*1e8);show();};
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}function bytes(s){return new TextEncoder().encode(s);}
async function exportPdf(){if(busy)return;busy=true;$('pdf').disabled=true;try{await render();const s=settings(),chunks=[],offsets=[0];let length=0;const push=b=>{chunks.push(b);length+=b.length;};push(bytes('%PDF-1.4\n'));const obj=(n,parts)=>{offsets[n]=length;push(bytes(`${n} 0 obj\n`));parts.forEach(push);push(bytes('\nendobj\n'));};const count=pages.length,ids=pages.map((_,i)=>3+i*3);obj(1,[bytes('<< /Type /Catalog /Pages 2 0 R >>')]);obj(2,[bytes(`<< /Type /Pages /Count ${count} /Kids [${ids.map(n=>n+' 0 R').join(' ')}] >>`)]);const off=document.createElement('canvas');for(let i=0;i<count;i++){status(`Preparando el PDF… ${i+1}/${count}`);draw(off,pages[i],s,i);const blob=await new Promise(resolve=>off.toBlob(resolve,'image/jpeg',.92));const img=new Uint8Array(await blob.arrayBuffer()),n=ids[i],pw=s.size==='a4'?595.28:612,ph=s.size==='a4'?841.89:792,scale=Math.min(pw/off.width,ph/off.height),iw=off.width*scale,ih=off.height*scale,stream=bytes(`q ${iw} 0 0 ${ih} ${(pw-iw)/2} ${(ph-ih)/2} cm /Im0 Do Q`);obj(n,[bytes(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 ${n+1} 0 R >> >> /Contents ${n+2} 0 R >>`)]);obj(n+1,[bytes(`<< /Type /XObject /Subtype /Image /Width ${off.width} /Height ${off.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${img.length} >>\nstream\n`),img,bytes('\nendstream')]);obj(n+2,[bytes(`<< /Length ${stream.length} >>\nstream\n`),stream,bytes('\nendstream')]);await new Promise(resolve=>setTimeout(resolve,0));}const xref=length;push(bytes(`xref\n0 ${offsets.length}\n0000000000 65535 f \n${offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`));download(new Blob(chunks,{type:'application/pdf'}),'manuscrito.pdf');status(`PDF generado: ${count} hojas.`);}catch(e){status('No se pudo exportar: '+e.message);}finally{busy=false;$('pdf').disabled=false;}}
$('pdf').onclick=exportPdf;$('png').onclick=async()=>{await render();canvas.toBlob(blob=>{if(blob)download(blob,`manuscrito-hoja-${current+1}.png`);},'image/png');};
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>30*1024*1024){status('El límite de importación es 30 MB. Divide el documento e importa una parte.');e.target.value='';return;}status('Leyendo tu documento…');try{let text='';if(file.name.toLowerCase().endsWith('.txt'))text=await file.text();else{const pdfjs=await import('./pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='./pdf-worker.mjs';const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;try{for(let i=1;i<=pdf.numPages;i++){status(`Leyendo página ${i} de ${pdf.numPages}…`);const p=await pdf.getPage(i),content=await p.getTextContent();let lastY=null;for(const item of content.items){if(!('str' in item))continue;const y=item.transform[5];if(lastY!==null&&Math.abs(y-lastY)>4)text+='\n';text+=item.str+(item.hasEOL?'\n':' ');lastY=item.hasEOL?null:y;}text+='\n\n';p.cleanup();}}finally{await pdf.destroy();}}if(!text.trim()){status('El PDF no contiene texto extraíble. Usa OCR para un documento escaneado.');return;}if(text.length>150000)throw new Error('El texto supera 150 000 caracteres. Importa el documento por partes.');$('text').value=text.trim();current=0;await render();status('Contenido importado. Revisa párrafos, fórmulas y orden antes de exportar.');}catch(err){status('No se pudo importar: '+err.message);}finally{e.target.value='';}};
function base64(buffer){let s='';for(const b of new Uint8Array(buffer))s+=String.fromCharCode(b);return btoa(s);}async function addFont(data){const f=new FontFace('Personal',data);await f.load();document.fonts.add(f);if(!Array.from($('font').options).some(o=>o.value==='Personal'))$('font').add(new Option('Mi propia letra','Personal'));$('font').value='Personal';}
$('fontFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>3*1024*1024)throw new Error('La fuente debe pesar menos de 3 MB.');customFontData=await f.arrayBuffer();await addFont(customFontData);await render();status('Tu fuente está lista.');}catch(err){status('No se pudo cargar la fuente: '+err.message);}finally{e.target.value='';}};
$('project').onclick=()=>{download(new Blob([JSON.stringify({version:1,text:$('text').value,settings:settings(),seed,customFont:customFontData?base64(customFontData):null})],{type:'application/json'}),'manuscrito-proyecto.json');status('Proyecto exportado. Puedes abrirlo aquí para seguir editando.');};$('openProject').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>6*1024*1024)throw new Error('Archivo demasiado grande.');const p=JSON.parse(await f.text());if(p.version!==1||typeof p.text!=='string'||p.text.length>150000)throw new Error('Formato de proyecto no válido.');if(p.customFont){customFontData=Uint8Array.from(atob(p.customFont),c=>c.charCodeAt(0)).buffer;await addFont(customFontData);}for(const id of ids){const el=$(id),v=p.settings?.[id];if(v===undefined)continue;if(el.type==='range'){if(Number.isFinite(+v))el.value=Math.min(+el.max,Math.max(+el.min,+v));}else if(Array.from(el.options).some(o=>o.value===v))el.value=v;}$('text').value=p.text;seed=Number.isFinite(p.seed)?p.seed:1729;current=0;await render();status('Proyecto abierto.');}catch(err){status('No se pudo abrir: '+err.message);}finally{e.target.value='';}};await render();
